<template><AppShell><PageHeader title="Inventory History"/><DataTable :columns="columns" :rows="rows"/></AppShell></template><script>import AppShell from '../../Components/AppShell.vue'; import PageHeader from '../../Components/PageHeader.vue'; import DataTable from '../../Components/DataTable.vue'; export default{components:{AppShell,PageHeader,DataTable},props:{transactions:Object},computed:{columns(){return[{key:'product',label:'Product'},{key:'warehouse',label:'Warehouse'},{key:'movement_type',label:'Movement'},{key:'quantity',label:'Quantity'},{key:'flagged',label:'Audit'}]},rows(){return this.transactions.data.map(function(row){return{id:row.id,product:row.product.name,warehouse:row.warehouse.name,movement_type:row.movement_type,quantity:row.quantity,flagged:row.flagged_for_review?'Flagged':'Clear'}})}}}</script>